import{c as r,Q as a,j as o,m as t}from"./chunks/framework.BXc4yaFE.js";const w=JSON.parse('{"title":"BayesFlow: A Probability Inference Framework for Meta-Agent Assisted Workflow Generation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2601.22305","title":"BayesFlow: A Probability Inference Framework for Meta-Agent Assisted Workflow Generation","archived_date":"2026-07-18T00:00:00.000Z","arxiv_id":2601.22305,"authors":["Bo Yuan","Yun Zhou","Zhichao Xu","Kiran Ramnath","Aosong Feng","Balasubramaniam Srinivasan"],"pdf_path":"pdfs/2601.22305.pdf","published_date":"2026-01-29T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-01-29-bayesflow-probability-inference-workflow-generation-2601-22305.md","filePath":"research/papers/2026-01-29-bayesflow-probability-inference-workflow-generation-2601-22305.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-01-29-bayesflow-probability-inference-workflow-generation-2601-22305.md"};function s(i,e,l,f,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="bayesflow-a-probability-inference-framework-for-meta-agent-assisted-workflow-generation" tabindex="-1">BayesFlow: A Probability Inference Framework for Meta-Agent Assisted Workflow Generation <a class="header-anchor" href="#bayesflow-a-probability-inference-framework-for-meta-agent-assisted-workflow-generation" aria-label="Permalink to &quot;BayesFlow: A Probability Inference Framework for Meta-Agent Assisted Workflow Generation&quot;">​</a></h1><p><strong>Authors</strong>: Bo Yuan, Yun Zhou, Zhichao Xu, Kiran Ramnath, Aosong Feng, Balasubramaniam Srinivasan <strong>Published</strong>: January 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2601.22305" target="_blank" rel="noreferrer">https://arxiv.org/abs/2601.22305</a><strong>arXiv ID</strong>: 2601.22305 <strong>Categories</strong>: Computer Science &gt; Machine Learning (cs.LG) <strong>PDF</strong>: <a href="https://arxiv.org/abs/2601.22305" target="_blank" rel="noreferrer">research/papers/pdfs/2601.22305.pdf</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>The research addresses automatic workflow generation—synthesizing sequences of LLM calls, tool invocations, and processing steps for complex tasks. Rather than treating this as a pure optimization problem, the authors reframe workflow generation as Bayesian inference over a posterior distribution on workflows. They introduce Bayesian Workflow Generation (BWG), a sampling framework that builds workflows step-by-step using parallel look-ahead rollouts for importance weighting. The instantiation called BayesFlow requires no training and achieved improvements of up to 9 percentage points over SOTA workflow generation baselines and by up to 65 percentage points over zero-shot prompting across six benchmark datasets. The authors provide theoretical convergence guarantees and have committed to releasing code.</p><hr><h2 id="core-thesis" tabindex="-1">Core Thesis <a class="header-anchor" href="#core-thesis" aria-label="Permalink to &quot;Core Thesis&quot;">​</a></h2><ul><li>把自動 workflow 生成（LLM call、工具呼叫、處理步驟序列的合成）從純最佳化問題重新框架為「workflow 後驗分佈上的貝氏推論」，而非搜尋單一最優解。</li><li>提出 Bayesian Workflow Generation (BWG)：用平行 look-ahead rollout 做重要性加權，逐步取樣建構 workflow；具體實作 BayesFlow 免訓練即可用。</li><li>六個 benchmark 上，相較 SOTA workflow 生成基準最多提升 9 個百分點，相較 zero-shot prompting 最多提升 65 個百分點；並提供理論收斂保證，程式碼承諾開源。</li><li><strong>Workspace 關聯</strong>：與本庫既有 Loop/Workflow Engineering 收錄論文（sew-2505-18646、workflow-opt-survey-2603-22386）互補——提供「用貝氏推論取代搜尋/RL」的另一種 workflow 生成理論視角，免訓練特性對成本敏感場景（如 <code>/pilot cost</code> 檔位任務規劃）有參考價值。</li></ul>',8)])])}const g=r(n,[["render",s]]);export{w as __pageData,g as default};
